-- Mission story, proof and things to know for every launch company
UPDATE public.stocks SET mission_story = 'Develops medicines and vaccines, led by Keytruda, an immunotherapy that helps the immune system find and attack cancer.', proof = 'Keytruda was the world''s best-selling medicine in 2024, with about $29 billion in sales.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=MRK&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Keytruda''s main U.S. patents begin expiring in 2028, a known challenge for Merck''s growth.']::text[], in_feed = true WHERE ticker = 'MRK';
UPDATE public.stocks SET mission_story = 'Develops medicines for cancer, blood disorders, immune diseases and heart disease, including the cancer immunotherapy Opdivo.', proof = 'Opdivo is approved for many cancers, including lung, skin, kidney and bladder cancer.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=BMY&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Several top drugs, including Eliquis and Opdivo, face patent expirations later this decade.']::text[], in_feed = true WHERE ticker = 'BMY';
UPDATE public.stocks SET mission_story = 'One of the world''s largest drugmakers, with medicines and vaccines for cancer, infections, heart disease and more.', proof = 'Pfizer bought cancer-drug developer Seagen in 2023 for about $43 billion to expand its cancer medicines.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=PFE&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Sales of its COVID-19 products have fallen sharply since 2022.']::text[], in_feed = true WHERE ticker = 'PFE';
UPDATE public.stocks SET mission_story = 'Develops medicines for immune diseases, cancer and brain conditions, plus Botox through its Allergan business.', proof = 'Its cancer drugs include Imbruvica and Venclexta, used to treat blood cancers such as leukemia.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ABBV&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Its former top seller, Humira, now faces lower-cost biosimilar competition.']::text[], in_feed = true WHERE ticker = 'ABBV';
UPDATE public.stocks SET mission_story = 'A biotechnology pioneer making medicines for cancer, bone loss, heart disease and inflammation.', proof = 'Its cancer medicines include Kyprolis for multiple myeloma and Blincyto for leukemia.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=AMGN&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Its 2023 purchase of Horizon Therapeutics added significant debt.']::text[], in_feed = true WHERE ticker = 'AMGN';
UPDATE public.stocks SET mission_story = 'Discovers antibody medicines for eye disease, allergies, asthma and cancer, using its own genetic research tools.', proof = 'Its Libtayo is an approved immunotherapy for certain skin and lung cancers.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=REGN&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Much of its income still depends on the eye drug Eylea, which faces new competition.']::text[], in_feed = true WHERE ticker = 'REGN';
UPDATE public.stocks SET mission_story = 'Develops medicines for HIV, liver disease and cancer, including cell therapies that reprogram immune cells to fight cancer.', proof = 'Its Kite unit makes the CAR T-cell therapies Yescarta and Tecartus for blood cancers.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=GILD&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Most of its sales still come from HIV medicines rather than cancer.']::text[], in_feed = true WHERE ticker = 'GILD';
UPDATE public.stocks SET mission_story = 'Develops mRNA medicines and vaccines, including its COVID-19 vaccine, an RSV vaccine and experimental personalized cancer vaccines.', proof = 'Its mRNA COVID-19 vaccine was one of the first two COVID-19 vaccines authorized in the U.S., in December 2020.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=MRNA&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Not profitable since COVID-19 vaccine demand fell, and the stock is very volatile.']::text[], in_feed = true WHERE ticker = 'MRNA';
UPDATE public.stocks SET mission_story = 'A German biotech developing cancer immunotherapies and vaccines, best known for co-developing the Pfizer-BioNTech COVID-19 vaccine.', proof = 'It co-developed the first COVID-19 vaccine authorized in the U.S., in December 2020.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=BNTX&type=20-F&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Results swing with vaccine demand, and it reports as a foreign company (Form 20-F).']::text[], in_feed = true WHERE ticker = 'BNTX';
UPDATE public.stocks SET mission_story = 'Develops medicines that treat the root causes of serious diseases like cystic fibrosis and sickle cell disease.', proof = 'Its Casgevy, approved in 2023, was the first approved CRISPR gene-editing therapy.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=VRTX&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Most of its revenue still comes from cystic fibrosis medicines.']::text[], in_feed = true WHERE ticker = 'VRTX';
UPDATE public.stocks SET mission_story = 'Develops therapies for neurological diseases such as multiple sclerosis, spinal muscular atrophy and Alzheimer''s disease.', proof = 'It co-developed Leqembi, approved in 2023 as a treatment that slows early Alzheimer''s disease.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=BIIB&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Its older multiple sclerosis drugs face falling sales from generic competition.']::text[], in_feed = true WHERE ticker = 'BIIB';
UPDATE public.stocks SET mission_story = 'Makes tools used to research diseases, manufacture biologic medicines and diagnose patients, through brands like Cytiva, Beckman Coulter and Cepheid.', proof = 'Its Cepheid GeneXpert systems are used worldwide to diagnose tuberculosis and other infections.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=DHR&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Demand for its tools slowed after the COVID-19 testing boom ended.']::text[], in_feed = true WHERE ticker = 'DHR';
UPDATE public.stocks SET mission_story = 'Develops blood tests that find cancer and help doctors choose treatments, without needing a tissue biopsy.', proof = 'Its Shield test became the first FDA-approved blood test for primary colorectal cancer screening, in 2024.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=GH&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Not yet profitable; growth depends on doctors and insurers adopting its tests.']::text[], in_feed = true WHERE ticker = 'GH';
UPDATE public.stocks SET mission_story = 'Develops genetic blood tests that check whether cancer has returned, screen pregnancies and monitor transplanted organs.', proof = 'Its Signatera test is personalized to each patient''s tumor to detect cancer recurrence from a blood draw.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=NTRA&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Has a history of losses while investing heavily in growth.']::text[], in_feed = true WHERE ticker = 'NTRA';
UPDATE public.stocks SET mission_story = 'Makes the DNA sequencing machines labs use to read genes, study cancer and diagnose genetic disease.', proof = 'Its technology helped cut the cost of sequencing a human genome from millions of dollars to a few hundred.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ILMN&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Spun off the cancer-test maker Grail in 2024 after regulators challenged the acquisition.']::text[], in_feed = true WHERE ticker = 'ILMN';
UPDATE public.stocks SET mission_story = 'Develops medicines for blood cancers, other cancers and inflammatory skin conditions.', proof = 'Its drug Jakafi treats myelofibrosis and polycythemia vera, two rare blood cancers.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=INCY&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Jakafi, its main drug, loses U.S. patent protection later this decade.']::text[], in_feed = true WHERE ticker = 'INCY';
UPDATE public.stocks SET mission_story = 'A focused cancer-drug company whose main medicine treats kidney, liver and thyroid cancers.', proof = 'Its drug Cabometyx is approved for advanced kidney cancer, liver cancer and certain thyroid cancers.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=EXEL&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Depends heavily on a single drug, Cabometyx.']::text[], in_feed = true WHERE ticker = 'EXEL';
UPDATE public.stocks SET mission_story = 'Pioneered medicines that switch off disease-causing genes, starting with rare inherited diseases and expanding into heart disease.', proof = 'Its Onpattro, approved in 2018, was the first FDA-approved RNAi medicine.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ALNY&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Has spent heavily on research, and its profits depend on a few key medicines.']::text[], in_feed = true WHERE ticker = 'ALNY';
UPDATE public.stocks SET mission_story = 'Develops medicines for rare genetic diseases that often have few or no other treatments.', proof = 'Its Voxzogo was the first approved medicine to increase growth in children with achondroplasia, the most common form of dwarfism.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=BMRN&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Rare-disease medicines serve small patient groups, so each launch matters a lot.']::text[], in_feed = true WHERE ticker = 'BMRN';
UPDATE public.stocks SET mission_story = 'Makes the kits and tests labs use to extract and analyze DNA, including tests for tuberculosis, infections and cancer markers.', proof = 'Its QuantiFERON test is widely used to screen for latent tuberculosis infection.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=QGEN&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Incorporated in the Netherlands, so results are sensitive to currency moves.']::text[], in_feed = true WHERE ticker = 'QGEN';
UPDATE public.stocks SET mission_story = 'Makes medical devices, diagnostic tests, nutrition products and medicines, including the FreeStyle Libre glucose monitor.', proof = 'Its FreeStyle Libre glucose monitors are used by millions of people with diabetes worldwide.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ABT&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Faces lawsuits over formula products for premature infants.']::text[], in_feed = true WHERE ticker = 'ABT';
UPDATE public.stocks SET mission_story = 'Makes continuous glucose monitors that let people with diabetes track their blood sugar in real time without finger pricks.', proof = 'In 2024 it launched Stelo, the first over-the-counter glucose biosensor cleared by the FDA.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=DXCM&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Faces strong competition from Abbott''s FreeStyle Libre.']::text[], in_feed = true WHERE ticker = 'DXCM';
UPDATE public.stocks SET mission_story = 'Makes the Omnipod, a small tubeless insulin pump worn on the body, for people with diabetes.', proof = 'Omnipod 5 works with continuous glucose monitors to adjust insulin delivery automatically.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=PODD&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Competes with larger device makers and newer diabetes medicines.']::text[], in_feed = true WHERE ticker = 'PODD';
UPDATE public.stocks SET mission_story = 'Makes the da Vinci robotic surgery system, which helps surgeons perform minimally invasive operations.', proof = 'Surgeons have performed millions of procedures with da Vinci systems since its first FDA clearance in 2000.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ISRG&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['The stock is valued at a high multiple of earnings.']::text[], in_feed = true WHERE ticker = 'ISRG';
UPDATE public.stocks SET mission_story = 'Makes heart valves and devices that let doctors replace or repair heart valves without open-heart surgery.', proof = 'It pioneered transcatheter aortic valve replacement (TAVR), which replaces a heart valve through a catheter.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=EW&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Sold its critical care business in 2024 to focus on structural heart devices.']::text[], in_feed = true WHERE ticker = 'EW';
UPDATE public.stocks SET mission_story = 'Makes devices for heart, vascular, digestive and urological conditions, including treatments for irregular heartbeat.', proof = 'Its Farapulse system uses pulsed electric fields to treat atrial fibrillation, a common irregular heartbeat.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=BSX&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Has grown through many acquisitions, which carry integration risk.']::text[], in_feed = true WHERE ticker = 'BSX';
UPDATE public.stocks SET mission_story = 'One of the largest medical device companies, making pacemakers, insulin pumps, spine and surgical tools.', proof = 'Its Micra is a leadless pacemaker small enough to be placed directly in the heart through a vein.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=MDT&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Growth has been slower than at smaller device makers.']::text[], in_feed = true WHERE ticker = 'MDT';
UPDATE public.stocks SET mission_story = 'Makes orthopedic implants, surgical equipment and robotic systems for joint replacement.', proof = 'Its Mako robotic-arm system assists surgeons with knee and hip replacements.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=SYK&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Hospital spending cycles can affect equipment sales.']::text[], in_feed = true WHERE ticker = 'SYK';
UPDATE public.stocks SET mission_story = 'Makes knee and hip replacement implants and related surgical technology.', proof = 'It is one of the largest makers of knee and hip replacement implants.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ZBH&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Its growth has lagged rivals, and it has faced product recalls.']::text[], in_feed = true WHERE ticker = 'ZBH';
UPDATE public.stocks SET mission_story = 'Makes CPAP machines and masks that treat sleep apnea, plus cloud software that tracks patients'' therapy.', proof = 'Its AirSense devices connect to the cloud so care teams can see how patients are using their therapy.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=RMD&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Weight-loss drugs could reduce sleep apnea cases over time, a debated risk to its sales.']::text[], in_feed = true WHERE ticker = 'RMD';
UPDATE public.stocks SET mission_story = 'Makes a small implant that treats sleep apnea by keeping the airway open during sleep, for people who can''t tolerate CPAP.', proof = 'Its therapy works by stimulating the nerve that moves the tongue, keeping the airway open during sleep.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=INSP&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Weight-loss drugs and competing devices are watched closely as risks to growth.']::text[], in_feed = true WHERE ticker = 'INSP';
UPDATE public.stocks SET mission_story = 'Makes Zio, a wearable patch that records heart rhythms for up to two weeks to help detect conditions like atrial fibrillation.', proof = 'Its Zio patch is worn for up to 14 days, and the recordings are analyzed with AI-assisted software.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=IRTC&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Not yet consistently profitable and depends on insurance reimbursement rates.']::text[], in_feed = true WHERE ticker = 'IRTC';
UPDATE public.stocks SET mission_story = 'Makes devices that remove blood clots from arteries and veins, used to treat strokes and blood clots in the lungs.', proof = 'Its computer-assisted vacuum devices pull clots out through a thin catheter.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=PEN&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Competition in clot-removal devices is increasing.']::text[], in_feed = true WHERE ticker = 'PEN';
UPDATE public.stocks SET mission_story = 'Develops tiny implants and drug-delivery treatments for glaucoma and other chronic eye diseases.', proof = 'Its iStent is among the smallest medical devices ever approved by the FDA.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=GKOS&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Not consistently profitable, and new products depend on insurance coverage decisions.']::text[], in_feed = true WHERE ticker = 'GKOS';
UPDATE public.stocks SET mission_story = 'Keeps donor hearts, lungs and livers warm and functioning outside the body, and flies them to transplant centers.', proof = 'Its Organ Care System keeps donor organs perfused and working during transport instead of packing them on ice.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=TMDX&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['A volatile stock; growth depends on transplant volumes and its aviation logistics.']::text[], in_feed = true WHERE ticker = 'TMDX';
UPDATE public.stocks SET mission_story = 'Helps hospitals and device makers prevent infections with sterilization equipment, services and supplies.', proof = 'It sterilizes medical devices for manufacturers and surgical instruments for hospitals.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=STE&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['A steady but slower-growing business tied to hospital procedure volumes.']::text[], in_feed = true WHERE ticker = 'STE';
UPDATE public.stocks SET mission_story = 'Runs one of the largest networks of medical testing labs, used for checkups, disease screening and diagnosis.', proof = 'Quest says it serves about one in three U.S. adults each year.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=DGX&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Lab testing prices are pressured by insurers and government reimbursement rules.']::text[], in_feed = true WHERE ticker = 'DGX';
UPDATE public.stocks SET mission_story = 'Runs medical testing labs used by doctors and patients, and supports the development of new medicines.', proof = 'Labcorp processes hundreds of millions of lab tests each year.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=LH&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Spun off its clinical-trials business, Fortrea, in 2023.']::text[], in_feed = true WHERE ticker = 'LH';
UPDATE public.stocks SET mission_story = 'Develops medicines for diabetes, obesity, cancer, immune diseases and Alzheimer''s disease.', proof = 'Its tirzepatide is sold as Mounjaro for diabetes and Zepbound for weight loss.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=LLY&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Its stock price assumes strong long-term growth from obesity medicines.']::text[], in_feed = true WHERE ticker = 'LLY';
UPDATE public.stocks SET mission_story = 'A Danish drugmaker focused on diabetes and obesity, the maker of insulin, Ozempic and Wegovy.', proof = 'Novo Nordisk has made insulin since the 1920s.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=NVO&type=20-F&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Faces intense competition from Eli Lilly in obesity medicines, and reports as a foreign company (Form 20-F).']::text[], in_feed = true WHERE ticker = 'NVO';
UPDATE public.stocks SET mission_story = 'Owns Florida''s largest electric utility and one of the world''s largest developers of wind and solar power.', proof = 'Its NextEra Energy Resources unit is one of the world''s largest generators of power from wind and sun.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=NEE&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Its Florida utility still generates much of its power from natural gas.']::text[], in_feed = true WHERE ticker = 'NEE';
UPDATE public.stocks SET mission_story = 'Makes thin-film solar panels using a different technology from most rivals, with large factories in the United States.', proof = 'It is the largest U.S.-based solar panel manufacturer.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=FSLR&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Its profits depend partly on U.S. clean-energy tax credits.']::text[], in_feed = true WHERE ticker = 'FSLR';
UPDATE public.stocks SET mission_story = 'Makes microinverters and home batteries that turn rooftop solar into usable electricity and store it.', proof = 'It pioneered microinverters, which convert power at each solar panel instead of at one central inverter.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ENPH&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Home solar demand has fallen with higher interest rates, and the stock is volatile.']::text[], in_feed = true WHERE ticker = 'ENPH';
UPDATE public.stocks SET mission_story = 'Makes solar trackers that tilt panels to follow the sun, helping large solar farms produce more power.', proof = 'It has been one of the world''s largest solar tracker suppliers by shipments for years.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=NXT&type=10-K&dateb=&owner=include&count=40',
