UPDATE public.stocks SET mission_story = 'Makes trackers that move solar panels to follow the sun at large solar power plants.', proof = 'It has been building solar tracking systems since 1989.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ARRY&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Smaller and more volatile than its main rival, Nextpower.']::text[], in_feed = true WHERE ticker = 'ARRY';
UPDATE public.stocks SET mission_story = 'Makes fuel-cell power systems that generate electricity on-site with lower emissions than burning fuel.', proof = 'Its fuel cells produce electricity through an electrochemical reaction rather than combustion.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=BE&type=10-K&dateb=&owner=include&count=40',
