UPDATE public.stocks SET mission_story = 'Builds large battery systems that store electricity for the grid, making wind and solar power more reliable.', proof = 'It was formed in 2018 by Siemens and AES, two longtime energy companies.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=FLNC&type=10-K&dateb=&owner=include&count=40',
