UPDATE public.stocks SET mission_story = 'Operates the largest fleet of nuclear power plants in the U.S., the country''s biggest source of carbon-free electricity.', proof = 'It is the largest producer of carbon-free energy in the United States.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=CEG&type=10-K&dateb=&owner=include&count=40',
