UPDATE public.stocks SET mission_story = 'Owns one of the world''s largest portfolios of renewable power, from hydroelectric dams to wind and solar farms.', proof = 'In 2024 it agreed to supply Microsoft with more than 10.5 gigawatts of new renewable power.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=BEP&type=20-F&dateb=&owner=include&count=40',
