UPDATE public.stocks SET mission_story = 'Owns wind, solar and battery projects across the U.S. and pays out much of its cash flow as dividends.', proof = 'It sells most of its power under long-term contracts with utilities and companies.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=CWEN&type=10-K&dateb=&owner=include&count=40',
