UPDATE public.stocks SET mission_story = 'Generates electricity from the Earth''s heat, one of the few renewable sources that runs around the clock.', proof = 'It has been developing geothermal power technology since the 1960s.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ORA&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Geothermal projects take years to develop and are capital-intensive.']::text[], in_feed = true WHERE ticker = 'ORA';
UPDATE public.stocks SET mission_story = 'Invests in and lends to clean energy and climate projects, from solar and wind to energy efficiency.', proof = 'It reports the carbon emissions its investments avoid each year, using a metric it calls CarbonCount.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=HASI&type=10-K&dateb=&owner=include&count=40',
