UPDATE public.stocks SET mission_story = 'The largest U.S. home solar company, installing rooftop solar and batteries that households lease or buy.', proof = 'It is the largest residential solar installer in the United States.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=RUN&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Carries a lot of debt and depends on tax credits; the stock is very volatile.']::text[], in_feed = true WHERE ticker = 'RUN';
UPDATE public.stocks SET mission_story = 'Makes electric vehicles, home and grid batteries, and solar products, and is developing self-driving technology.', proof = 'Its Megapack batteries store electricity at grid scale, and energy storage is one of its fastest-growing businesses.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=TSLA&type=10-K&dateb=&owner=include&count=40',
