UPDATE public.stocks SET mission_story = 'Builds wind turbines and the grid equipment that carries power, and services a large share of the world''s power plants.', proof = 'It was spun off from General Electric in 2024 as GE''s energy business.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=GEV&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['A large part of its business is gas turbines for fossil-fuel power plants.']::text[], in_feed = true WHERE ticker = 'GEV';
UPDATE public.stocks SET mission_story = 'Makes electrical equipment that manages power in buildings, data centers and grids, helping electrify the economy.', proof = 'Its products include equipment that connects solar, batteries and EV chargers to buildings and the grid.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ETN&type=10-K&dateb=&owner=include&count=40',
