UPDATE public.stocks SET mission_story = 'A global power company shifting toward wind, solar and batteries, and a major supplier of clean power to tech companies.', proof = 'It has signed long-term clean-power contracts with large tech companies, including Google and Microsoft.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=AES&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Still operates coal and gas plants and carries significant debt.']::text[], in_feed = true WHERE ticker = 'AES';
UPDATE public.stocks SET mission_story = 'A utility serving eight states and one of the largest providers of wind power among U.S. utilities.', proof = 'In 2018 it became the first major U.S. utility to commit to 100% carbon-free electricity by 2050.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=XEL&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Still burns coal and natural gas for part of its power.']::text[], in_feed = true WHERE ticker = 'XEL';
UPDATE public.stocks SET mission_story = 'A large utility serving 11 states and the owner of one of the largest U.S. electricity transmission networks.', proof = 'It operates the largest electricity transmission system in the United States.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=AEP&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Coal and natural gas still make up a large share of its generation.']::text[], in_feed = true WHERE ticker = 'AEP';
UPDATE public.stocks SET mission_story = 'One of the world''s largest lithium producers, supplying a key material for electric-vehicle and grid batteries.', proof = 'It produces lithium from brine in Chile and from hard-rock mines in Australia.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ALB&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Lithium prices swing widely, making profits and the stock volatile.']::text[], in_feed = true WHERE ticker = 'ALB';
UPDATE public.stocks SET mission_story = 'Protects computers, cloud systems and user identities from cyberattacks with its Falcon platform.', proof = 'Its Falcon platform uses a single lightweight agent on each device to detect and stop attacks.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=CRWD&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['A faulty software update in July 2024 crashed millions of Windows computers worldwide.']::text[], in_feed = true WHERE ticker = 'CRWD';
UPDATE public.stocks SET mission_story = 'One of the largest cybersecurity companies, protecting networks, cloud systems and security operations.', proof = 'Its customers include most of the Fortune 100.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=PANW&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Agreed in 2025 to buy CyberArk, its largest acquisition.']::text[], in_feed = true WHERE ticker = 'PANW';
UPDATE public.stocks SET mission_story = 'Makes firewalls and network security systems that protect businesses from cyberattacks.', proof = 'It designs its own security chips to speed up its firewalls.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=FTNT&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Sales depend partly on hardware upgrade cycles.']::text[], in_feed = true WHERE ticker = 'FTNT';
UPDATE public.stocks SET mission_story = 'Provides cloud-based security that connects employees to apps safely without a traditional company network.', proof = 'Its cloud processes hundreds of billions of transactions a day.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ZS&type=10-K&dateb=&owner=include&count=40',
