UPDATE public.stocks SET mission_story = 'Runs a global network that protects websites and apps from attacks and makes them faster.', proof = 'Its network runs in more than 300 cities worldwide.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=NET&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Highly valued relative to its current profits.']::text[], in_feed = true WHERE ticker = 'NET';
UPDATE public.stocks SET mission_story = 'Provides identity software that controls who can sign in to apps and systems.', proof = 'It offers identity tools for both employees and customers, including the Auth0 platform.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=OKTA&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Suffered a security breach of its customer support system in 2023.']::text[], in_feed = true WHERE ticker = 'OKTA';
UPDATE public.stocks SET mission_story = 'Uses AI to detect and stop cyberattacks on computers, cloud systems and identities automatically.', proof = 'Its platform can roll a Windows device back to its state before a ransomware attack.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=S&type=10-K&dateb=&owner=include&count=40',
