UPDATE public.stocks SET mission_story = 'One of the original cybersecurity companies, protecting networks, cloud systems and email from attacks.', proof = 'It helped pioneer the commercial firewall in the 1990s.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=CHKP&type=20-F&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Grows more slowly than newer rivals, and reports as a foreign company (Form 20-F).']::text[], in_feed = true WHERE ticker = 'CHKP';
UPDATE public.stocks SET mission_story = 'Finds security weaknesses in computer systems before attackers can exploit them.', proof = 'It created Nessus, one of the most widely used vulnerability scanners.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=TENB&type=10-K&dateb=&owner=include&count=40',
