UPDATE public.stocks SET mission_story = 'Helps security teams find weak spots and detect attacks across their systems.', proof = 'It maintains Metasploit, a widely used open-source tool for testing security.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=RPD&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Faces tough competition and slowing growth.']::text[], in_feed = true WHERE ticker = 'RPD';
UPDATE public.stocks SET mission_story = 'Scans companies'' computers and cloud systems for security weaknesses and compliance gaps.', proof = 'It was one of the first companies to deliver security scanning as a cloud service.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=QLYS&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['A smaller company facing larger, faster-growing competitors.']::text[], in_feed = true WHERE ticker = 'QLYS';
UPDATE public.stocks SET mission_story = 'Protects sensitive data by finding where it lives, who can access it, and spotting suspicious activity.', proof = 'It focuses on protecting data itself, such as files and email, rather than the network around it.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=VRNS&type=10-K&dateb=&owner=include&count=40',
