UPDATE public.stocks SET mission_story = 'Protects companies'' data with backups that attackers can''t change, helping them recover from ransomware.', proof = 'Its backups are designed to be immutable, so ransomware can''t alter or delete them.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=RBRK&type=10-K&dateb=&owner=include&count=40',
