UPDATE public.stocks SET mission_story = 'Makes Norton, Avast and LifeLock, protecting everyday people from viruses, scams and identity theft.', proof = 'It says its products protect around 500 million users worldwide.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=GEN&type=10-K&dateb=&owner=include&count=40',
