UPDATE public.stocks SET mission_story = 'The largest maker of networking equipment, with a growing security business that includes Splunk.', proof = 'It bought Splunk in 2024 for about $28 billion, expanding its security business.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=CSCO&type=10-K&dateb=&owner=include&count=40',
