UPDATE public.stocks SET mission_story = 'Makes safety gear that protects firefighters and workers, from breathing equipment to gas detectors and hard hats.', proof = 'It was founded in 1914 to make safety equipment for coal miners.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=MSA&type=10-K&dateb=&owner=include&count=40',
  things_to_know = ARRAY['Sales depend on industrial and fire-department budgets.']::text[], in_feed = true WHERE ticker = 'MSA';
