  things_to_know = ARRAY['Carries a lot of debt.']::text[], in_feed = true WHERE ticker = 'ADT';
UPDATE public.stocks SET mission_story = 'Makes locks and access systems, including Schlage, that secure homes, schools and businesses.', proof = 'It owns Schlage, a lock brand founded in 1920.', proof_source_url = 'https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=ALLE&type=10-K&dateb=&owner=include&count=40',
